function atomic(file,data){const b=Buffer.isBuffer(data)?data:Buffer.from(data),tmp=`${file}.tmp-${process.pid}`;fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(tmp,b,{flag:"wx"});fs.renameSync(tmp,file)}
async function get(url,cap=16*1024*1024,timeout=40000){const c=new AbortController(),t=setTimeout(()=>c.abort(),timeout);try{const r=await fetch(url,{signal:c.signal,redirect:"follow",headers:{accept:"application/json,text/plain","user-agent":"evm-audit-free-step2/1.0"}});if(!r.ok)throw Object.assign(Error("GET failed"),{status:r.status});const chunks=[];let n=0;for await(const ch of r.body){n+=ch.length;if(n>cap)throw Error("response-cap");chunks.push(ch)}const raw=Buffer.concat(chunks);return{raw,bytes:n,sha256:sha256(raw)}}finally{clearTimeout(t)}}
let rpcId=1;
async function rpc(url,method,params,timeout=30000){const c=new AbortController(),t=setTimeout(()=>c.abort(),timeout);try{const r=await fetch(url,{method:"POST",signal:c.signal,headers:{"content-type":"application/json","user-agent":"evm-audit-free-step2/1.0"},body:JSON.stringify({jsonrpc:"2.0",id:rpcId++,method,params})});if(!r.ok)throw Object.assign(Error("RPC failed"),{status:r.status});const j=await r.json();if(j.error)throw Object.assign(Error("RPC error"),{code:j.error.code});return j.result}finally{clearTimeout(t)}}
async function rpcBatch(url,calls,chunkSize=100){const results=[];for(let start=0;start<calls.length;start+=chunkSize){const chunk=calls.slice(start,start+chunkSize),ids=chunk.map(()=>rpcId++),payload=chunk.map((x,i)=>({jsonrpc:"2.0",id:ids[i],method:x.method,params:x.params}));try{const c=new AbortController(),t=setTimeout(()=>c.abort(),60000);let json;try{const r=await fetch(url,{method:"POST",signal:c.signal,headers:{"content-type":"application/json","user-agent":"evm-audit-free-step2/1.0"},body:JSON.stringify(payload)});if(!r.ok)throw Object.assign(Error("batch RPC failed"),{status:r.status});json=await r.json()}finally{clearTimeout(t)}const by=new Map((Array.isArray(json)?json:[]).map(x=>[x.id,x]));for(const idv of ids){const row=by.get(idv);results.push(row?.error?{status:"failure",error:`error:${row.error.code}`}:{status:"success",value:row?.result})}}catch(e){for(const x of chunk)try{results.push({status:"success",value:await rpc(url,x.method,x.params)})}catch(er){results.push({status:"failure",error:err(er)})}}}return results}

function bindStep1(){
  const rb=fs.readFileSync(STEP1_RAW),mb=fs.readFileSync(STEP1_MANIFEST),m=parse(mb,"Step1 manifest"),r=parse(rb,"Step1 raw");
  const checks={manifestRawHash:m.files?.raw?.sha256===sha256(rb),runId:m.runId===r.runId,classification:r.classification===STEP1_CLASSIFICATION,
    requiredGates:r.gates?.requiredStep1GatesPassed===true,sourceProvider:r.gates?.sourceProviderVerified===true,abiAgreement:r.gates?.sourceAbiAgreement===true,
    noPromotion:r.gates?.vulnerabilityPromoted===false&&r.gates?.routePositive===0};
  if(!Object.values(checks).every(Boolean))throw Error(`Step1 binding failed: ${Object.entries(checks).filter(([,v])=>!v).map(([k])=>k).join(",")}`);
  const eth=r.adapter?.inventory?.find(x=>x.chain==="ethereum")?.owners;
  if(canonicalText(eth)!==canonicalText(OWNERS.map(x=>x.address)))throw Error("Step1 Ethereum owner set mismatch");
  return{raw:{file:rel(STEP1_RAW),sha256:sha256(rb),bytes:rb.length},manifest:{file:rel(STEP1_MANIFEST),sha256:sha256(mb),bytes:mb.length},runId:r.runId,classification:r.classification,checks};
}
async function selectProvider(){const attempts=[];for(let i=0;i<RPC_FALLBACKS.length;i++){const u=RPC_FALLBACKS[i];try{const chain=await rpc(u,"eth_chainId",[]),block=await rpc(u,"eth_getBlockByNumber",[PIN_HEX,false]);let historical=false;if(chain==="0x1"&&block?.hash?.toLowerCase()===PIN_HASH){historical=true;for(const o of OWNERS){const code=await rpc(u,"eth_getCode",[o.address,PIN_HEX]);if(!/^0x[0-9a-fA-F]*$/.test(code)||code==="0x"){historical=false;break}}if(historical){const s=await rpc(u,"eth_getStorageAt",[OWNERS[1].address,IMPL_SLOT,PIN_HEX]);historical=/^0x[0-9a-fA-F]{64}$/.test(s)}}attempts.push({fallbackIndex:i+1,chainId:chain==="0x1"?"pass":"fail",pinHash:block?.hash?.toLowerCase()===PIN_HASH?"pass":"fail",requiredHistoricalCalls:historical?"pass":"fail"});if(historical)return{url:u,evidence:{fallbackIndex:i+1,chainId:1,pinBlock:PIN,pinHash:PIN_HASH,pinTimestamp:Number.parseInt(block.timestamp,16),attempts}}}catch(e){attempts.push({fallbackIndex:i+1,status:"unavailable",error:err(e)})}}throw Error(`no archive provider passed: ${JSON.stringify(attempts)}`)}

